import PocketBase from 'pocketbase';

const pb = new PocketBase(process.env.BACKEND_URL || 'http://pocketbase:8090');

async function setupCollections() {
  console.log('Setting up PocketBase collections...');

  // Authenticate as admin (PocketBase default admin setup needed)
  // For initial setup, we'll use the API directly

  try {
    // Create habits collection
    try {
      await pb.collections.create({
        name: 'habits',
        type: 'base',
        schema: [
          {
            name: 'user_id',
            type: 'relation',
            required: true,
            options: {
              collectionId: '_pb_users_auth_',
              cascadeDelete: false,
              minSelect: null,
              maxSelect: 1,
              displayFields: []
            }
          },
          {
            name: 'name',
            type: 'text',
            required: true,
            options: {
              min: 1,
              max: 80,
              pattern: ''
            }
          },
          {
            name: 'description',
            type: 'text',
            required: false,
            options: {
              min: null,
              max: 200,
              pattern: ''
            }
          },
          {
            name: 'color',
            type: 'select',
            required: true,
            options: {
              maxSelect: 1,
              values: ['indigo', 'teal', 'amber', 'rose', 'slate', 'forest']
            }
          },
          {
            name: 'deleted',
            type: 'bool',
            required: false,
            options: {}
          }
        ],
        indexes: [
          'CREATE UNIQUE INDEX idx_unique_user_name ON habits (user_id, LOWER(name)) WHERE deleted = FALSE'
        ],
        listRule: '@request.auth.id != "" && user_id = @request.auth.id && deleted = false',
        viewRule: '@request.auth.id != "" && user_id = @request.auth.id',
        createRule: '@request.auth.id != "" && @request.data.user_id = @request.auth.id',
        updateRule: '@request.auth.id != "" && user_id = @request.auth.id',
        deleteRule: '@request.auth.id != "" && user_id = @request.auth.id'
      });
      console.log('✓ habits collection created');
    } catch (err) {
      if (err.status === 400 && err.data?.data?.name) {
        console.log('✓ habits collection already exists');
      } else {
        throw err;
      }
    }

    // Create completions collection
    try {
      await pb.collections.create({
        name: 'completions',
        type: 'base',
        schema: [
          {
            name: 'user_id',
            type: 'relation',
            required: true,
            options: {
              collectionId: '_pb_users_auth_',
              cascadeDelete: false,
              minSelect: null,
              maxSelect: 1,
              displayFields: []
            }
          },
          {
            name: 'habit_id',
            type: 'relation',
            required: true,
            options: {
              collectionId: '', // Will be set after habits collection exists
              cascadeDelete: false,
              minSelect: null,
              maxSelect: 1,
              displayFields: []
            }
          },
          {
            name: 'date',
            type: 'text',
            required: true,
            options: {
              min: null,
              max: null,
              pattern: '^\\d{4}-\\d{2}-\\d{2}$'
            }
          }
        ],
        indexes: [
          'CREATE UNIQUE INDEX idx_unique_completion ON completions (user_id, habit_id, date)'
        ],
        listRule: '@request.auth.id != "" && user_id = @request.auth.id',
        viewRule: '@request.auth.id != "" && user_id = @request.auth.id',
        createRule: '@request.auth.id != "" && @request.data.user_id = @request.auth.id',
        updateRule: null,
        deleteRule: '@request.auth.id != "" && user_id = @request.auth.id'
      });
      console.log('✓ completions collection created');
    } catch (err) {
      if (err.status === 400 && err.data?.data?.name) {
        console.log('✓ completions collection already exists');
      } else {
        throw err;
      }
    }

    console.log('PocketBase collections setup complete!');
  } catch (error) {
    console.error('Error setting up collections:', error);
    throw error;
  }
}

setupCollections().catch(console.error);

