import PocketBase from 'pocketbase';

const BACKEND_URL = process.env.BACKEND_URL || 'http://pocketbase:8090';
const pb = new PocketBase(BACKEND_URL);

const DEMO_EMAIL = 'demo@ethara.ai';
const DEMO_PASSWORD = 'deku-demo-pw-2026';

async function getTodayUTC() {
  const now = new Date();
  return now.toISOString().split('T')[0];
}

async function getDateOffset(daysAgo) {
  const date = new Date();
  date.setDate(date.getDate() - daysAgo);
  return date.toISOString().split('T')[0];
}

async function initDatabase() {
  console.log('Initializing PocketBase database...');

  try {
    // Step 1: Check if demo user exists, create if not
    let demoUser;
    try {
      const users = await pb.collection('users').getFullList({
        filter: `email = "${DEMO_EMAIL}"`
      });

      if (users.length > 0) {
        demoUser = users[0];
        console.log('✓ Demo user already exists');
      } else {
        // Create demo user
        demoUser = await pb.collection('users').create({
          email: DEMO_EMAIL,
          password: DEMO_PASSWORD,
          passwordConfirm: DEMO_PASSWORD,
          emailVisibility: true
        });
        console.log('✓ Demo user created');
      }
    } catch (err) {
      console.error('Error with demo user:', err);
      throw err;
    }

    // Authenticate as demo user for subsequent operations
    await pb.collection('users').authWithPassword(DEMO_EMAIL, DEMO_PASSWORD);
    console.log('✓ Authenticated as demo user');

    // Step 2: Check if habits exist, create if not
    const existingHabits = await pb.collection('habits').getFullList({
      filter: `user_id = "${demoUser.id}" && deleted = false`
    });

    const habitNames = ['Meditate', 'Read 20 minutes', 'No soda'];
    const habitColors = ['indigo', 'teal', 'amber'];
    const habits = [];

    for (let i = 0; i < habitNames.length; i++) {
      const existingHabit = existingHabits.find(h => h.name === habitNames[i]);

      if (existingHabit) {
        habits.push(existingHabit);
        console.log(`✓ Habit "${habitNames[i]}" already exists`);
      } else {
        const habit = await pb.collection('habits').create({
          user_id: demoUser.id,
          name: habitNames[i],
          color: habitColors[i],
          deleted: false
        });
        habits.push(habit);
        console.log(`✓ Habit "${habitNames[i]}" created`);
      }
    }

    // Step 3: Create completions to achieve the required streaks
    const today = await getTodayUTC();

    // Meditate: current_streak of 5 (today + 4 previous days)
    const meditateHabit = habits[0];
    for (let i = 0; i < 5; i++) {
      const date = await getDateOffset(i);
      try {
        await pb.collection('completions').create({
          user_id: demoUser.id,
          habit_id: meditateHabit.id,
          date: date
        });
        console.log(`✓ Meditate completion created for ${date}`);
      } catch (err) {
        if (err.status === 400) {
          console.log(`  Meditate completion for ${date} already exists`);
        } else {
          throw err;
        }
      }
    }

    // Read 20 minutes: current_streak of 0, longest_streak of at least 3
    // Create 3 consecutive days earlier this month (e.g., days 7-9 ago)
    const readHabit = habits[1];
    for (let i = 7; i <= 9; i++) {
      const date = await getDateOffset(i);
      try {
