    const result = await apiCall('/api/admins/auth-with-password', {
      method: 'POST',
      body: JSON.stringify({
        identity: ADMIN_EMAIL,
        password: ADMIN_PASSWORD
      })
    });

    if (result.ok) {
      adminToken = result.data.token;
      console.log('✓ Admin authenticated');
      return;
    }
  } catch (err) {
    // Admin doesn't exist or wrong password, continue to creation
  }

  // If no admin exists, PocketBase allows creating the first one without auth
  try {
    const result = await apiCall('/api/admins', {
      method: 'POST',
      body: JSON.stringify({
        email: ADMIN_EMAIL,
        password: ADMIN_PASSWORD,
        passwordConfirm: ADMIN_PASSWORD
      })
    });

    if (result.ok || result.status === 400) {
      // Now authenticate
      const authResult = await apiCall('/api/admins/auth-with-password', {
        method: 'POST',
        body: JSON.stringify({
          identity: ADMIN_EMAIL,
          password: ADMIN_PASSWORD
        })
      });

      if (authResult.ok) {
        adminToken = authResult.data.token;
        console.log('✓ Admin created and authenticated');
      }
    }
  } catch (err) {
    console.log('Note: Using existing admin setup');
  }
}

async function createCollection(config) {
  const result = await apiCall('/api/collections', {
    method: 'POST',
    body: JSON.stringify(config)
  });

  if (result.ok) {
    console.log(`✓ Collection "${config.name}" created`);
    return result.data;
  } else if (result.status === 400 && result.data.data?.name) {
    console.log(`✓ Collection "${config.name}" already exists`);
    // Get the existing collection
    const getResult = await apiCall(`/api/collections/${config.name}`);
    return getResult.data;
  } else {
    throw new Error(`Failed to create collection ${config.name}`);
  }
}

async function setupCollections() {
  console.log('\nSetting up collections...');

  // Create habits collection
  const habitsCollection = await createCollection({
    name: 'habits',
    type: 'base',
    schema: [
      {
        name: 'user_id',
        type: 'relation',
        required: true,
        options: {
          collectionId: 'users',
          cascadeDelete: false,
          maxSelect: 1
        }
      },
      {
        name: 'name',
        type: 'text',
        required: true,
        options: { min: 1, max: 80 }
      },
      {
        name: 'description',
        type: 'text',
        required: false,
        options: { max: 200 }
      },
      {
        name: 'color',
        type: 'select',
        required: true,
        options: {
          maxSelect: 1,
          values: ['indigo', 'teal', 'amber', 'rose', 'slate', 'forest']
        }
      },
      {
        name: 'deleted',
        type: 'bool',
        required: false
      }
    ],
    indexes: [
      'CREATE UNIQUE INDEX IF NOT EXISTS idx_unique_user_name ON habits (user_id, LOWER(name)) WHERE deleted = FALSE'
    ],
    listRule: '@request.auth.id != "" && user_id = @request.auth.id && deleted = false',
    viewRule: '@request.auth.id != "" && user_id = @request.auth.id',
    createRule: '@request.auth.id != "" && @request.data.user_id = @request.auth.id',
    updateRule: '@request.auth.id != "" && user_id = @request.auth.id',
    deleteRule: '@request.auth.id != "" && user_id = @request.auth.id'
  });

  // Create completions collection
  await createCollection({
    name: 'completions',
    type: 'base',
    schema: [
      {
        name: 'user_id',
        type: 'relation',
        required: true,
        options: {
          collectionId: 'users',
          cascadeDelete: false,
          maxSelect: 1
        }
      },
      {
        name: 'habit_id',
        type: 'relation',
        required: true,
        options: {
          collectionId: habitsCollection.id,
          cascadeDelete: false,
          maxSelect: 1
        }
      },
      {
        name: 'date',
        type: 'text',
        required: true,
        options: { pattern: '^\\d{4}-\\d{2}-\\d{2}$' }
      }
    ],
    indexes: [
      'CREATE UNIQUE INDEX IF NOT EXISTS idx_unique_completion ON completions (user_id, habit_id, date)'
    ],
    listRule: '@request.auth.id != "" && user_id = @request.auth.id',
    viewRule: '@request.auth.id != "" && user_id = @request.auth.id',
    createRule: '@request.auth.id != "" && @request.data.user_id = @request.auth.id',
    updateRule: null,
    deleteRule: '@request.auth.id != "" && user_id = @request.auth.id'
  });
}

async function getDateOffset(daysAgo) {
  const date = new Date();
  date.setDate(date.getDate() - daysAgo);
  return date.toISOString().split('T')[0];
}

async function seedData() {
  console.log('\nSeeding data...');

  // Create/get demo user
  let demoUser;
  const usersResult = await apiCall(`/api/collections/users/records?filter=email='${DEMO_EMAIL}'`);

  if (usersResult.data.items && usersResult.data.items.length > 0) {
    demoUser = usersResult.data.items[0];
    console.log('✓ Demo user already exists');
  } else {
    const createResult = await apiCall('/api/collections/users/records', {
      method: 'POST',
      body: JSON.stringify({
        email: DEMO_EMAIL,
        password: DEMO_PASSWORD,
        passwordConfirm: DEMO_PASSWORD,
        emailVisibility: true
      })
    });

    if (createResult.ok) {
      demoUser = createResult.data;
      console.log('✓ Demo user created');
    } else {
      throw new Error('Failed to create demo user');
    }
  }

  // Authenticate as demo user to create habits
  const authResult = await apiCall('/api/collections/users/auth-with-password', {
    method: 'POST',
    body: JSON.stringify({
      identity: DEMO_EMAIL,
      password: DEMO_PASSWORD
    })
  });

  if (!authResult.ok) {
    throw new Error('Failed to authenticate demo user');
  }

  const userToken = authResult.data.token;

  // Create habits
  const habitData = [
    { name: 'Meditate', color: 'indigo' },
    { name: 'Read 20 minutes', color: 'teal' },
    { name: 'No soda', color: 'amber' }
  ];

  const habits = [];
  for (const habit of habitData) {
    const existingResult = await apiCall(
      `/api/collections/habits/records?filter=user_id='${demoUser.id}' && name='${habit.name}' && deleted=false`,
      { headers: { Authorization: userToken } }
    );

    if (existingResult.data.items && existingResult.data.items.length > 0) {
      habits.push(existingResult.data.items[0]);
      console.log(`✓ Habit "${habit.name}" already exists`);
    } else {
      const createResult = await apiCall('/api/collections/habits/records', {
        method: 'POST',
        headers: { Authorization: userToken },
        body: JSON.stringify({
          user_id: demoUser.id,
          name: habit.name,
          color: habit.color,
          deleted: false
        })
      });

      if (createResult.ok) {
        habits.push(createResult.data);
        console.log(`✓ Habit "${habit.name}" created`);
      }
    }
  }

  // Create completions
  const today = await getDateOffset(0);

  // Meditate: 5-day streak (today + 4 previous)
  for (let i = 0; i < 5; i++) {
    const date = await getDateOffset(i);
    const result = await apiCall('/api/collections/completions/records', {
      method: 'POST',
      headers: { Authorization: userToken },
      body: JSON.stringify({
        user_id: demoUser.id,
        habit_id: habits[0].id,
        date: date
      })
    });

    if (result.ok || result.status === 400) {
      console.log(`✓ Meditate completion: ${date}`);
    }
  }

  // Read 20 minutes: 3-day streak 7-9 days ago
  for (let i = 7; i <= 9; i++) {
    const date = await getDateOffset(i);
    const result = await apiCall('/api/collections/completions/records', {
      method: 'POST',
      headers: { Authorization: userToken },
      body: JSON.stringify({
        user_id: demoUser.id,
        habit_id: habits[1].id,
        date: date
      })
    });

    if (result.ok || result.status === 400) {
      console.log(`✓ Read completion: ${date}`);
    }
  }

  // No soda: 1-day streak (today only)
  const result = await apiCall('/api/collections/completions/records', {
    method: 'POST',
    headers: { Authorization: userToken },
    body: JSON.stringify({
      user_id: demoUser.id,
      habit_id: habits[2].id,
      date: today
    })
  });

  if (result.ok || result.status === 400) {
    console.log(`✓ No soda completion: ${today}`);
  }

  console.log('\n✅ Bootstrap complete!');
  console.log(`\nDemo credentials:`);
  console.log(`  Email: ${DEMO_EMAIL}`);
  console.log(`  Password: ${DEMO_PASSWORD}\n`);
}

async function main() {
  try {
    await setupAdmin();
    await setupCollections();
    await seedData();
  } catch (error) {
    console.error('\n❌ Bootstrap failed:', error);
    process.exit(1);
  }
}

main();

